```go
package main

import "fmt"

type Point struct {
    X int
    Y int
}

func main() {
    keyed := Point{Y: 4, X: 3}
    positional := Point{3, 4}
    fmt.Println(keyed, positional, keyed == positional)
}
```
The output ends in `true`. The keyed literal may list fields in either order; the positional literal follows `X`, then `Y`.

```go
package main

import "fmt"

type Config struct {
    Host  string
    Port  int
    Debug bool
}

func NewConfig() Config {
    return Config{Host: "localhost", Port: 8080}
}

func main() {
    partial := Config{Port: 3000}
    defaults := NewConfig()
    fmt.Printf("%q %d %t\n", partial.Host, partial.Port, partial.Debug)
    fmt.Println(defaults)
}
```
The omitted `Host` is empty and `Debug` is false. Only `NewConfig` supplies application defaults.

```go
package main

import "fmt"

type Point struct{ X, Y int }

func main() {
    value := Point{X: 2}
    pointer := &Point{X: 2}
    zero := new(Point)
    pointer.Y = 4
    fmt.Printf("%T %v\n", value, value)
    fmt.Printf("%T %v\n", pointer, *pointer)
    fmt.Printf("%T %v\n", zero, *zero)
}
```
The types are `main.Point`, `*main.Point`, and `*main.Point`; the last pointed-to value contains only zeros.
